void Boss::update(double dt) {
  phaseTimer_ += dt;
  switch (phase_) {
    case Phase::Roar:
      if (phaseTimer_ >= 1.0) enter(Phase::Charge);
      break;
    case Phase::Charge:
      moveToward(player(), CHARGE_SPEED * dt);
      if (inMeleeRange()) { slashCount_ = 0; enter(Phase::Slash); }
      break;
    case Phase::Slash:
      if (phaseTimer_ >= 0.3) {
        slash();
        phaseTimer_ = 0;
        if (++slashCount_ == 3) enter(Phase::Rest);
      }
      break;
    case Phase::Rest:
      if (phaseTimer_ >= 2.0) enter(Phase::Roar);
      break;
  }
}

void World::update() {
  int numObjectsThisTurn = numObjects_;   // new spawns wait a frame
  for (int i = 0; i < numObjectsThisTurn; i++) {
    if (objects_[i]->isDead()) continue;  // skip corpses
    objects_[i]->update();
  }

  // Remove the dead after iteration is finished.
  int alive = 0;
  for (int i = 0; i < numObjects_; i++) {
    if (objects_[i]->isDead()) delete objects_[i];
    else objects_[alive++] = objects_[i];
  }
  numObjects_ = alive;
}

void Patroller::update(double elapsed) {
  double step = speed_ * elapsed;
  if (movingLeft_) {
    x_ -= step;
    if (x_ <= minX_) { x_ = minX_ + (minX_ - x_); movingLeft_ = false; }
  } else {
    x_ += step;
    if (x_ >= maxX_) { x_ = maxX_ - (x_ - maxX_); movingLeft_ = true; }
  }
  x_ = std::clamp(x_, minX_, maxX_);  // huge elapsed: stay in range
}

class Monster {
public:
  void update() { behavior_->update(*this); } // non-virtual, delegates
  void setBehavior(Behavior* b) { behavior_ = b; }
private:
  Behavior* behavior_;
};

class Zone {
public:
  void activate(Monster* m)   { activeList_.push_back(m); }
  void deactivate(Monster* m) { removeFrom(activeList_, m); }
  void update() {
    for (Monster* m : activeList_) m->update();  // ~500, not 10000
  }
private:
  std::vector<Monster*> all_;         // master list
  std::vector<Monster*> activeList_;  // only live objects
};
